/**
 * 导航 — 6 个有效页面
 * Home · Customers · Pricing · AI Engine · Help · About
 * @author 恒哥
 */
import React from 'react';
import { Link } from 'gatsby';
import { useLocation } from '@reach/router';
import { SHOPIFY_INSTALL_PAGE_PATH } from '../../constants/brand';
import './navigation.css';

const NAV_ITEMS = [
  { to: '/', label: 'Home', match: (p) => p === '/' || p === '' },
  { to: '/customers/', label: 'Customers', match: (p) => p.startsWith('/customers') },
  { to: '/pricing/', label: 'Pricing', match: (p) => p.startsWith('/pricing') },
  {
    to: '/features/ai-email-engine/',
    label: 'AI Engine',
    match: (p) => p.startsWith('/features/ai-email-engine'),
  },
  {
    to: '/help/',
    label: 'Help',
    match: (p) => p.startsWith('/cart-rescue') || p.startsWith('/help'),
  },
  { to: '/about/', label: 'About', match: (p) => p.startsWith('/about') },
];

export default function Navigation() {
  const { pathname } = useLocation();

  return (
    <nav className="navigation">
      <div className="nav-container">
        <Link to="/" className="nav-logo">
          <img
            src="/images/whaleal-icon.png"
            width="56"
            height="56"
            alt="Whaleal"
            className="logo-image"
          />
          <span className="nav-brand">
            <span className="nav-brand-name">Whaleal</span>
            <span className="nav-brand-tagline">whaleal.com</span>
          </span>
        </Link>
        <div className="nav-links">
          {NAV_ITEMS.map((item) => (
            <Link
              key={item.to}
              to={item.to}
              className={`nav-link ${item.match(pathname) ? 'nav-link-active' : ''}`}
            >
              {item.label}
            </Link>
          ))}
        </div>
        <div className="nav-actions">
          <Link to={SHOPIFY_INSTALL_PAGE_PATH} className="nav-button nav-button-primary">
            Install free
          </Link>
        </div>
      </div>
    </nav>
  );
}
